{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "celular batería larga duración",
        "category": "celulares",
        "attributes": {"bateria_mah": {"min": 5000}},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "get_reviews",
      "args": {"product_id": "$s1.0.id", "limit": 3}
    },
    {
      "id": "s3",
      "op": "get_reviews",
      "args": {"product_id": "$s1.1.id", "limit": 3}
    },
    {
      "id": "s4",
      "op": "compare_products",
      "args": {"ids": ["$s1.0.id", "$s1.1.id"]}
    },
    {
      "id": "s5",
      "op": "respond",
      "plantilla": "Para alguien que pasa el día fuera sin acceso a cargador, te recomiendo estos celulares con batería de 5000 mAh o más:\n\n1. **{nombre0}** — ${precio0} CLP <<rec:{id0}>>\nReseñas: {resenas0}\n\n2. **{nombre1}** — ${precio1} CLP <<rec:{id1}>>\nReseñas: {resenas1}\n\nComparación entre ambos: <<cmp:{id0},{id1}>>\nEl más barato es {mas_barato} y el mejor evaluado es {mejor_evaluado}.\n\n¿Te gustaría más detalles de alguno de ellos?",
      "vars": {
        "nombre0": "$s1.0.name",
        "precio0": "$s1.0.price_clp",
        "id0": "$s1.0.id",
        "resenas0": "$s2",
        "nombre1": "$s1.1.name",
        "precio1": "$s1.1.price_clp",
        "id1": "$s1.1.id",
        "resenas1": "$s3",
        "mas_barato": "$s4.mas_barato",
        "mejor_evaluado": "$s4.mejor_evaluado"
      }
    }
  ]
}
